"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { ArrowLeft, ArrowRight, Check as CheckIcon, CircleAlert, Cloud, Download, FileCheck2, FileImage, LoaderCircle, Plus, Printer, ShieldCheck, Trash2, UserRoundPlus } from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";
import { admissionDocumentCategoryLabels, completedAdmissionSchema, emergencyContactSchema, feeHandoffSchema, guardianSchema, healthSchema, learnerAdmissionSchema, pickupPersonSchema, residenceSchema } from "@/lib/admissions";
import { MAX_UPLOAD_FILE_BYTES } from "@/lib/upload-limits";

type Guardian = { fullName: string; relationship: string; idNumber: string; phone: string; alternatePhone: string; whatsapp: boolean; email: string; occupation: string; employer: string; homeAddress: string; workAddress: string; paysFees: boolean; primaryContact: boolean };
type Contact = { fullName: string; relationship: string; phone: string };
type WizardData = { learner: Record<string, string | string[]>; residence: Record<string, string | number | null>; guardians: Guardian[]; emergencyContacts: Contact[]; pickupPersons: Contact[]; health: Record<string, string>; fee: { term: string; feePayerGuardian: string; requestedOptionalItems: string[]; handoffNote: string }; consent: boolean };
type Document = { id: string; category: string; originalName: string; contentType: string; sizeBytes: number };
type DraftState = { id: string; admissionNo: string; currentStep: number; status: string; learner?: { id: string; name: string; grade: string; admissionStatus: string; hasLearnerLogin?: boolean } | null; payload?: unknown; documents?: Document[] };

const stepNames = ["Learner", "Residence", "Family", "Health", "Documents", "Fees", "Review"];
const gradeOptions = ["PP1", "PP2", ...Array.from({ length: 9 }, (_, i) => `Grade ${i + 1}`)];
const categories = Object.entries(admissionDocumentCategoryLabels);
const blankGuardian = (): Guardian => ({ fullName: "", relationship: "Mother", idNumber: "", phone: "", alternatePhone: "", whatsapp: false, email: "", occupation: "", employer: "", homeAddress: "", workAddress: "", paysFees: true, primaryContact: true });
const blankContact = (): Contact => ({ fullName: "", relationship: "", phone: "" });
const emptyData: WizardData = {
  learner: { fullName: "", dateOfBirth: "", gender: "Female", nationality: "Kenyan", upiNumber: "", grade: "Grade 1", stream: "", admissionDate: new Date().toISOString().slice(0, 10), previousSchool: "", previousClass: "", reasonForLeaving: "", religion: "", languagesSpoken: ["English", "Kiswahili"] },
  residence: { county: "Kisumu", subCounty: "Kisumu Central", ward: "", village: "", physicalAddress: "", landmark: "", distanceToSchoolKm: "", transportMeans: "", latitude: "", longitude: "" },
  guardians: [blankGuardian()], emergencyContacts: [blankContact(), blankContact()], pickupPersons: [],
  health: { knownConditions: "", allergies: "", currentMedication: "", specialNeeds: "", bloodGroup: "", doctorOrHospital: "", immunizationStatus: "", healthInsurance: "" },
  fee: { term: "", feePayerGuardian: "", requestedOptionalItems: [], handoffNote: "" }, consent: false
};
const inputClass = "mt-1.5 min-h-12 w-full rounded-xl border border-slate-200 bg-white px-3.5 text-sm text-slate-900 shadow-sm outline-none transition placeholder:text-slate-400 focus:border-blue-600 focus:ring-4 focus:ring-blue-100";
const selectClass = `${inputClass} pr-9`;
function clean(value: unknown): unknown {
  if (typeof value === "string") return value.trim() === "" ? undefined : value.trim();
  if (Array.isArray(value)) return value.map(clean).filter(item => item !== undefined);
  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, clean(item)]).filter(([, item]) => item !== undefined));
  return value;
}
function toDraftPayload(data: WizardData): unknown {
  const distance = data.residence.distanceToSchoolKm;
  const latitude = data.residence.latitude;
  const longitude = data.residence.longitude;
  return clean({ ...data, residence: { ...data.residence, distanceToSchoolKm: distance === "" ? undefined : Number(distance), latitude: latitude === "" ? undefined : Number(latitude), longitude: longitude === "" ? undefined : Number(longitude) } });
}
function errorMap(issues: { path: PropertyKey[]; message: string }[]) { return Object.fromEntries(issues.map(issue => [issue.path.join("."), issue.message])); }
function Field({ label, children, error, hint }: { label: string; children: React.ReactNode; error?: string; hint?: string }) { return <label className="block text-sm font-semibold text-slate-700">{label}{children}{hint && <span className="mt-1 block text-xs font-normal text-slate-500">{hint}</span>}{error && <span className="mt-1 block text-xs font-semibold text-red-700">{error}</span>}</label>; }
function TextField({ label, value, onChange, type = "text", placeholder, error, required = false }: { label: string; value: string; onChange: (value: string) => void; type?: string; placeholder?: string; error?: string; required?: boolean }) { return <Field label={label} error={error}><input required={required} type={type} value={value} onChange={event => onChange(event.target.value)} placeholder={placeholder} className={`${inputClass} ${error ? "border-red-300 focus:border-red-500 focus:ring-red-100" : ""}`}/></Field>; }
function AreaField({ label, value, onChange, error }: { label: string; value: string; onChange: (value: string) => void; error?: string }) { return <Field label={label} error={error}><textarea value={value} onChange={event => onChange(event.target.value)} rows={3} className={`${inputClass} py-3`}/></Field>; }
function Check({ checked, onChange, children }: { checked: boolean; onChange: (value: boolean) => void; children: React.ReactNode }) { return <label className="flex min-h-11 items-center gap-3 rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium text-slate-700"><input type="checkbox" checked={checked} onChange={event => onChange(event.target.checked)} className="h-4 w-4 rounded border-slate-300 text-blue-700 focus:ring-blue-600"/>{children}</label>; }

export default function AdmissionWizard({ initialId, canCreateLearnerLogin = true, canCreateAdmission = true }: { initialId?: string; canCreateLearnerLogin?: boolean; canCreateAdmission?: boolean }) {
  const router = useRouter();
  const createRequest = useRef<Promise<DraftState> | null>(null);
  const saveQueue = useRef<Promise<void>>(Promise.resolve());
  const [draft, setDraft] = useState<DraftState | null>(null);
  const [data, setData] = useState<WizardData>(emptyData);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [step, setStep] = useState(1);
  const [ready, setReady] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [saving, setSaving] = useState(false);
  const [savedAt, setSavedAt] = useState<Date | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loginDetails, setLoginDetails] = useState<{ email: string; temporaryPassword: string; suspended: boolean } | null>(null);
  const [guardianLoginDetails, setGuardianLoginDetails] = useState<{ email: string; temporaryPassword: string | null; linkedExisting: boolean; suspended: boolean } | null>(null);
  const [guardianIndex, setGuardianIndex] = useState("");
  const [loginBusy, setLoginBusy] = useState(false);

  const load = useCallback(async (id: string) => {
    const response = await fetch(`/api/admissions/${id}`, { cache: "no-store" });
    const result = await response.json();
    if (!response.ok) throw new Error(result.error ?? "Could not open this admission.");
    const found = result.draft as DraftState;
    setDraft(found); setDocuments(found.documents ?? []); setStep(found.currentStep || 1);
    const incoming = found.payload as Partial<WizardData> | undefined;
    if (incoming) setData({ ...emptyData, ...incoming, learner: { ...emptyData.learner, ...incoming.learner }, residence: { ...emptyData.residence, ...incoming.residence }, health: { ...emptyData.health, ...incoming.health }, fee: { ...emptyData.fee, ...incoming.fee }, guardians: incoming.guardians?.length ? incoming.guardians.map(person => ({ ...blankGuardian(), ...person })) as Guardian[] : emptyData.guardians, emergencyContacts: incoming.emergencyContacts?.length ? incoming.emergencyContacts.map(person => ({ ...blankContact(), ...person })) as Contact[] : emptyData.emergencyContacts, pickupPersons: incoming.pickupPersons?.length ? incoming.pickupPersons.map(person => ({ ...blankContact(), ...person })) as Contact[] : [] });
    setReady(true); setDirty(false);
  }, []);

  useEffect(() => {
    let active = true;
    if (initialId) { void load(initialId).catch(cause => { if (active) { setError(cause instanceof Error ? cause.message : "Could not open this admission."); setReady(true); } }); return () => { active = false; }; }
    if (!createRequest.current) createRequest.current = fetch("/api/admissions", { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }).then(async response => {
      const result = await response.json(); if (!response.ok) throw new Error(result.error ?? "Could not start an admission.");
      return result.draft as DraftState;
    });
    void createRequest.current.then(found => {
      if (!active) return;
      setDraft(found); setReady(true); setSavedAt(new Date()); router.replace(`/admissions/${found.id}`);
    }).catch(cause => { if (active) { setError(cause instanceof Error ? cause.message : "Could not start an admission."); setReady(true); } });
    return () => { active = false; };
  }, [initialId, load, router]);

  const saveDraft = useCallback((id: string, currentStep: number, current: WizardData) => {
    saveQueue.current = saveQueue.current.then(async () => {
      setSaving(true);
      const response = await fetch("/api/admissions", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id, step: currentStep, data: toDraftPayload(current) }) });
      const result = await response.json();
      if (!response.ok) throw new Error(result.error ?? "Draft could not be saved.");
      setDraft(previous => previous ? { ...previous, ...result.draft } : previous); setSavedAt(new Date());
    }).finally(() => setSaving(false));
    return saveQueue.current;
  }, []);

  useEffect(() => {
    if (!ready || !dirty || !draft || draft.status !== "DRAFT") return;
    const timer = setTimeout(() => { void saveDraft(draft.id, step, data).then(() => setDirty(false)).catch(cause => setError(cause instanceof Error ? cause.message : "Draft save failed.")); }, 850);
    return () => clearTimeout(timer);
  }, [data, dirty, draft, ready, saveDraft, step]);

  const updateSection = (section: "learner" | "residence" | "health" | "fee", key: string, value: unknown) => {
    setData(current => ({ ...current, [section]: { ...current[section], [key]: value } } as WizardData)); setDirty(true); setError("");
  };
  const updateGuardian = (index: number, key: keyof Guardian, value: string | boolean) => { setData(current => ({ ...current, guardians: current.guardians.map((person, row) => row === index ? { ...person, [key]: value } : person) })); setDirty(true); setError(""); };
  const updateContact = (list: "emergencyContacts" | "pickupPersons", index: number, key: keyof Contact, value: string) => { setData(current => ({ ...current, [list]: current[list].map((person, row) => row === index ? { ...person, [key]: value } : person) })); setDirty(true); setError(""); };
  const setErrorFromIssues = (issues: { path: PropertyKey[]; message: string }[]) => { const mapped = errorMap(issues); setErrors(mapped); setError(Object.values(mapped)[0] ?? "Check the highlighted fields."); };

  function validateStep(currentStep: number) {
    if (currentStep === 1) { const result = learnerAdmissionSchema.safeParse(data.learner); if (!result.success) { setErrorFromIssues(result.error.issues); return false; } }
    if (currentStep === 2) { const residence = { ...data.residence, distanceToSchoolKm: data.residence.distanceToSchoolKm === "" ? undefined : Number(data.residence.distanceToSchoolKm), latitude: data.residence.latitude === "" ? undefined : Number(data.residence.latitude), longitude: data.residence.longitude === "" ? undefined : Number(data.residence.longitude) }; const result = residenceSchema.safeParse(residence); if (!result.success) { setErrorFromIssues(result.error.issues); return false; } }
    if (currentStep === 3) {
      const guardianResult = data.guardians.length > 0 ? data.guardians.map(person => guardianSchema.safeParse(person)) : [];
      const emergencyResult = data.emergencyContacts.map(person => emergencyContactSchema.safeParse(person));
      const pickupResult = data.pickupPersons.map(person => pickupPersonSchema.safeParse(person));
      const issues = [...guardianResult.flatMap(result => result.success ? [] : result.error.issues), ...emergencyResult.flatMap(result => result.success ? [] : result.error.issues), ...pickupResult.flatMap(result => result.success ? [] : result.error.issues)];
      if (data.guardians.length === 0) issues.push({ code: "custom", path: ["guardians"], message: "Add at least one parent or guardian." });
      if (data.emergencyContacts.length < 2) issues.push({ code: "custom", path: ["emergencyContacts"], message: "Add at least two emergency contacts." });
      if (data.guardians.filter(person => person.primaryContact).length !== 1) issues.push({ code: "custom", path: ["guardians"], message: "Choose exactly one primary contact." });
      if (issues.length) { setErrorFromIssues(issues); return false; }
    }
    if (currentStep === 4) { const result = healthSchema.safeParse(data.health); if (!result.success) { setErrorFromIssues(result.error.issues); return false; } }
    if (currentStep === 6) { const result = feeHandoffSchema.safeParse(data.fee); if (!result.success) { setErrorFromIssues(result.error.issues); return false; } }
    setErrors({}); setError(""); return true;
  }

  async function next() {
    if (!validateStep(step) || !draft) return;
    setBusy(true);
    try { await saveDraft(draft.id, step + 1, data); setStep(value => Math.min(value + 1, 7)); setDirty(false); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Draft save failed."); }
    finally { setBusy(false); }
  }
  async function previous() { if (!draft) return; setError(""); setStep(value => Math.max(1, value - 1)); setDirty(true); }

  async function upload(category: string, file: File | undefined) {
    if (!draft || !file) return;
    if (file.size > MAX_UPLOAD_FILE_BYTES) { setError("Choose a file smaller than 4 MB."); return; }
    setBusy(true); setError("");
    try {
      const body = new FormData(); body.set("category", category); body.set("file", file);
      const response = await fetch(`/api/admissions/${draft.id}/documents`, { method: "POST", body }); const result = await response.json();
      if (!response.ok) throw new Error(result.error ?? "Upload failed.");
      setDocuments(current => [...current.filter(document => document.category !== category), result.document as Document]);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Upload failed."); }
    finally { setBusy(false); }
  }
  async function removeDocument(document: Document) {
    if (!draft || !window.confirm(`Remove ${document.originalName} from this draft?`)) return;
    const response = await fetch(`/api/admissions/${draft.id}/documents/${document.id}`, { method: "DELETE" }); const result = await response.json();
    if (!response.ok) { setError(result.error ?? "Could not remove the document."); return; }
    setDocuments(current => current.filter(item => item.id !== document.id));
  }
  async function submitAdmission() {
    if (!draft) return;
    const completed = completedAdmissionSchema.safeParse({ ...data, residence: { ...data.residence, distanceToSchoolKm: data.residence.distanceToSchoolKm === "" ? undefined : Number(data.residence.distanceToSchoolKm), latitude: data.residence.latitude === "" ? undefined : Number(data.residence.latitude), longitude: data.residence.longitude === "" ? undefined : Number(data.residence.longitude) } });
    if (!completed.success) { setErrorFromIssues(completed.error.issues); setStep(Math.max(1, stepForPath(completed.error.issues[0]?.path[0]))); return; }
    setBusy(true); setError("");
    try {
      await saveDraft(draft.id, 7, data);
      const response = await fetch(`/api/admissions/${draft.id}/submit`, { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }); const result = await response.json();
      if (!response.ok) throw new Error(result.error ?? "Admission could not be submitted.");
      const submitted = result.draft as { id: string; admissionNo: string; status: string };
      setDraft(current => current ? { ...current, ...submitted, learner: result.learner } : current); setDirty(false);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Admission could not be submitted."); }
    finally { setBusy(false); }
  }
  async function createLearnerLogin() {
    if (!draft?.learner) return;
    setLoginBusy(true); setError("");
    try { const response = await fetch(`/api/learners/${draft.learner.id}/login`, { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }); const result = await response.json(); if (!response.ok) throw new Error(result.error ?? "Could not create learner login."); setLoginDetails({ email: result.account.email, temporaryPassword: result.temporaryPassword, suspended: result.account.suspended }); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Could not create learner login."); }
    finally { setLoginBusy(false); }
  }
  async function createGuardianLogin() {
    if (!draft || guardianIndex === "") return;
    setLoginBusy(true); setError("");
    try {
      const response = await fetch(`/api/admissions/${draft.id}/guardian-login`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ guardianIndex: Number(guardianIndex) }) });
      const result = await response.json();
      if (!response.ok) throw new Error(result.error ?? "Could not create or link parent access.");
      setGuardianLoginDetails({ email: result.account.email, temporaryPassword: result.temporaryPassword ?? null, linkedExisting: !result.created, suspended: result.suspended });
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not create or link parent access."); }
    finally { setLoginBusy(false); }
  }
  async function startAnother() { router.push("/admissions/new"); }

  if (!ready || !draft) return <main className="mx-auto max-w-5xl p-5 pb-28 md:p-8"><div className="animate-pulse rounded-3xl border border-slate-200 bg-white p-8"><div className="h-6 w-40 rounded bg-slate-200"/><div className="mt-5 h-3 w-full rounded bg-slate-100"/><div className="mt-8 grid gap-4 sm:grid-cols-2"><div className="h-16 rounded-xl bg-slate-100"/><div className="h-16 rounded-xl bg-slate-100"/><div className="h-16 rounded-xl bg-slate-100"/><div className="h-16 rounded-xl bg-slate-100"/></div></div></main>;

  if (draft.status !== "DRAFT") return <main className="mx-auto max-w-4xl p-5 pb-28 md:p-8"><section className="rounded-3xl border border-emerald-100 bg-white p-6 shadow-sm sm:p-9"><div className="grid h-14 w-14 place-items-center rounded-2xl bg-emerald-50 text-emerald-700"><CheckIcon size={28}/></div><p className="mt-5 text-xs font-bold uppercase tracking-[.16em] text-emerald-700">Admission {draft.status === "ENROLLED" ? "approved" : "submitted"}</p><h1 className="mt-2 text-3xl font-extrabold tracking-tight text-slate-950">{draft.learner?.name ?? data.learner.fullName}</h1><p className="mt-2 text-slate-600">Admission number <strong className="text-blue-800">{draft.admissionNo}</strong> · {draft.learner?.grade ?? data.learner.grade}</p><p className="mt-3 max-w-xl text-sm leading-6 text-slate-600">{draft.status === "SUBMITTED" ? "The admission has been sent to the Head Teacher for approval. The Director can review the submitted record." : "The Head Teacher approved this admission. The Director can review the complete record and audit history."}</p><div className="mt-6 flex flex-wrap gap-3"><a href={`/api/admissions/${draft.id}/form`} className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-blue-700 px-4 text-sm font-bold text-white shadow-sm hover:bg-blue-800"><Download size={17}/> Download admission PDF</a><a href={`/api/admissions/${draft.id}/form?download=0`} target="_blank" rel="noreferrer" className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-slate-200 px-4 text-sm font-bold text-slate-700 hover:bg-slate-50"><Printer size={17}/> Print form</a>{canCreateLearnerLogin && draft.learner && !draft.learner.hasLearnerLogin && !loginDetails && <button type="button" disabled={loginBusy} onClick={() => void createLearnerLogin()} className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-blue-200 bg-blue-50 px-4 text-sm font-bold text-blue-800 disabled:opacity-60">{loginBusy ? <LoaderCircle className="animate-spin" size={17}/> : <UserRoundPlus size={17}/>} Create learner login</button>}{canCreateAdmission && draft.learner && data.guardians.length > 0 && !guardianLoginDetails && <div className="flex min-h-11 flex-wrap items-center gap-2"><select aria-label="Parent or guardian for account" value={guardianIndex} onChange={event => setGuardianIndex(event.target.value)} className="min-h-11 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="">Select a guardian</option>{data.guardians.map((guardian, index) => <option key={`${index}-${guardian.phone}`} value={index}>{guardian.fullName || `Guardian ${index + 1}`} · {guardian.relationship}</option>)}</select><button type="button" disabled={loginBusy || guardianIndex === ""} onClick={() => void createGuardianLogin()} className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-blue-200 bg-blue-50 px-4 text-sm font-bold text-blue-800 disabled:cursor-not-allowed disabled:opacity-50">{loginBusy ? <LoaderCircle className="animate-spin" size={16}/> : <UserRoundPlus size={16}/>} Create/link parent login</button></div>}
{guardianLoginDetails && <div className="mt-6 w-full rounded-2xl border border-blue-200 bg-blue-50 p-5"><p className="text-sm font-extrabold text-blue-950">{guardianLoginDetails.linkedExisting ? "Existing parent account linked" : "Parent credentials · shown once"}</p><p className="mt-2 text-sm text-slate-700">Sign-in email: <strong>{guardianLoginDetails.email}</strong></p>{guardianLoginDetails.temporaryPassword && <p className="mt-2 font-mono text-lg font-bold text-blue-900">Temporary password: {guardianLoginDetails.temporaryPassword}</p>}<p className="mt-2 text-xs text-slate-600">{guardianLoginDetails.linkedExisting ? "The matching parent account can now see this learner." : guardianLoginDetails.suspended ? "Access remains suspended until the learner is enrolled." : "The parent must change this password at first sign-in."} Share any new credentials privately.</p></div>}<Link href="/learners" className="inline-flex min-h-11 items-center rounded-xl border border-slate-200 px-4 text-sm font-bold text-slate-700 hover:bg-slate-50">Open learner register</Link>{canCreateAdmission && <button type="button" onClick={() => void startAnother()} className="min-h-11 rounded-xl px-4 text-sm font-bold text-blue-800 hover:bg-blue-50">Start another admission</button>}</div>{loginDetails && <div className="mt-6 rounded-2xl border border-blue-200 bg-blue-50 p-5"><p className="flex items-center gap-2 text-sm font-extrabold text-blue-950"><ShieldCheck size={18}/> Learner credentials · shown once</p><p className="mt-3 text-sm text-slate-700">Sign-in email: <strong>{loginDetails.email}</strong></p><p className="mt-2 font-mono text-lg font-bold text-blue-900">Temporary password: {loginDetails.temporaryPassword}</p><p className="mt-2 text-xs text-slate-600">{loginDetails.suspended ? "The account remains suspended until the Head Teacher approves this admission." : "The learner must change this password at first sign-in."} Share these details privately.</p></div>}</section></main>;

  const docsByCategory = new Map(documents.map(document => [document.category, document]));
  return <main className="mx-auto max-w-5xl p-4 pb-32 sm:p-6 sm:pb-32 lg:p-8"><div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><Link href="/admissions" className="inline-flex min-h-9 items-center gap-2 text-sm font-semibold text-blue-800 hover:underline"><ArrowLeft size={16}/> Admissions</Link><p className="mt-4 text-xs font-bold uppercase tracking-[.16em] text-blue-700">Mary Royal School · Obunga, Kisumu</p><h1 className="mt-1 text-3xl font-extrabold tracking-tight text-slate-950">New learner admission</h1><p className="mt-1 text-sm text-slate-500">A simple guided record. Your progress saves automatically.</p></div><div className="rounded-xl border border-blue-100 bg-white px-4 py-3"><p className="text-[10px] font-bold uppercase tracking-wider text-slate-500">Admission number</p><p className="mt-1 font-mono text-lg font-extrabold text-blue-800">{draft.admissionNo}</p></div></div>
    <form onSubmit={event => event.preventDefault()} className="rounded-3xl border border-slate-200/80 bg-white p-4 shadow-sm sm:p-6"><div className="flex items-center justify-between gap-3"><p className="text-sm font-extrabold text-slate-900">Step {step} of 7 <span className="font-medium text-slate-500">· {stepNames[step - 1]}</span></p><p aria-live="polite" className="inline-flex items-center gap-1.5 text-xs text-slate-500">{saving ? <><Cloud size={14}/> Saving…</> : savedAt ? <><CheckIcon size={14} className="text-emerald-700"/> Saved {savedAt.toLocaleTimeString("en-KE", { hour: "2-digit", minute: "2-digit" })}</> : "Autosaves as you go"}</p></div><div className="mt-4 grid grid-cols-7 gap-1.5" aria-label="Admission progress">{stepNames.map((name, index) => <div key={name} aria-label={`Step ${index + 1}: ${name}`} className={`h-1.5 rounded-full ${index + 1 <= step ? "bg-blue-700" : "bg-slate-100"}`}/>)}</div><nav className="mt-4 flex gap-2 overflow-x-auto pb-1" aria-label="Admission steps">{stepNames.map((name, index) => <button key={name} type="button" disabled={index + 1 > step || busy} onClick={() => { if (index + 1 < step) { setStep(index + 1); setDirty(true); } }} className={`min-h-9 shrink-0 rounded-lg px-3 text-xs font-bold ${step === index + 1 ? "bg-blue-50 text-blue-800" : index + 1 < step ? "text-blue-700 hover:bg-blue-50" : "text-slate-400"}`}>{index + 1}. {name}</button>)}</nav>
      {error && <div role="alert" className="mt-4 flex gap-2 rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-800"><CircleAlert size={18} className="mt-0.5 shrink-0"/><p>{error}</p></div>}
      <div className="mt-6 min-h-[420px]">
        {step === 1 && <section><SectionHeading title="Learner details" description="Start with the information used in the school register."/><div className="grid gap-4 sm:grid-cols-2"><TextField label="Full names" value={String(data.learner.fullName)} onChange={value => updateSection("learner", "fullName", value)} placeholder="Names as shown on birth certificate" error={errors.fullName} required/><TextField label="Date of birth" type="date" value={String(data.learner.dateOfBirth)} onChange={value => updateSection("learner", "dateOfBirth", value)} error={errors.dateOfBirth} required/><Field label="Gender"><select value={String(data.learner.gender)} onChange={event => updateSection("learner", "gender", event.target.value)} className={selectClass}><option>Female</option><option>Male</option></select></Field><TextField label="Nationality" value={String(data.learner.nationality)} onChange={value => updateSection("learner", "nationality", value)} error={errors.nationality} required/><TextField label="UPI / NEMIS number" value={String(data.learner.upiNumber)} onChange={value => updateSection("learner", "upiNumber", value)} placeholder="Optional if not yet assigned"/><Field label="Class applied for"><select value={String(data.learner.grade)} onChange={event => updateSection("learner", "grade", event.target.value)} className={selectClass}>{gradeOptions.map(grade => <option key={grade}>{grade}</option>)}</select></Field><TextField label="Stream" value={String(data.learner.stream)} onChange={value => updateSection("learner", "stream", value)} placeholder="e.g. East or Blue"/><TextField label="Admission date" type="date" value={String(data.learner.admissionDate)} onChange={value => updateSection("learner", "admissionDate", value)} error={errors.admissionDate} required/><TextField label="Previous school" value={String(data.learner.previousSchool)} onChange={value => updateSection("learner", "previousSchool", value)}/><TextField label="Last class attended" value={String(data.learner.previousClass)} onChange={value => updateSection("learner", "previousClass", value)}/><TextField label="Religion (optional)" value={String(data.learner.religion)} onChange={value => updateSection("learner", "religion", value)}/><TextField label="Languages spoken" value={(data.learner.languagesSpoken as string[]).join(", ")} onChange={value => updateSection("learner", "languagesSpoken", value.split(",").map(part => part.trim()).filter(Boolean))} placeholder="English, Kiswahili"/></div><div className="mt-4"><AreaField label="Reason for leaving previous school" value={String(data.learner.reasonForLeaving)} onChange={value => updateSection("learner", "reasonForLeaving", value)}/></div></section>}
        {step === 2 && <section><SectionHeading title="Residence and transport" description="Help the school understand where the learner lives and how they travel."/><div className="grid gap-4 sm:grid-cols-2"><TextField label="County" value={String(data.residence.county)} onChange={value => updateSection("residence", "county", value)} error={errors.county} required/><TextField label="Sub-county" value={String(data.residence.subCounty)} onChange={value => updateSection("residence", "subCounty", value)} error={errors.subCounty} required/><TextField label="Ward" value={String(data.residence.ward)} onChange={value => updateSection("residence", "ward", value)} error={errors.ward} required/><TextField label="Village / estate / area" value={String(data.residence.village)} onChange={value => updateSection("residence", "village", value)} error={errors.village} required/><TextField label="Physical address" value={String(data.residence.physicalAddress)} onChange={value => updateSection("residence", "physicalAddress", value)} error={errors.physicalAddress} required/><TextField label="Nearby landmark" value={String(data.residence.landmark)} onChange={value => updateSection("residence", "landmark", value)}/><TextField label="Distance to school (km)" type="number" value={String(data.residence.distanceToSchoolKm)} onChange={value => updateSection("residence", "distanceToSchoolKm", value)} placeholder="Optional"/><TextField label="Means of transport" value={String(data.residence.transportMeans)} onChange={value => updateSection("residence", "transportMeans", value)} placeholder="Walk, bus, matatu…"/><TextField label="Latitude (optional)" value={String(data.residence.latitude)} onChange={value => updateSection("residence", "latitude", value)} placeholder="Map pin coordinate"/><TextField label="Longitude (optional)" value={String(data.residence.longitude)} onChange={value => updateSection("residence", "longitude", value)} placeholder="Map pin coordinate"/></div></section>}
        {step === 3 && <section><SectionHeading title="Parents and guardians" description="At least one guardian and two emergency contacts are required."/><div className="space-y-4">{data.guardians.map((person, index) => <article key={index} className="rounded-2xl border border-slate-200 bg-slate-50/50 p-4 sm:p-5"><div className="mb-4 flex items-center justify-between"><h3 className="font-extrabold text-slate-900">Parent or guardian {index + 1}</h3>{data.guardians.length > 1 && <button type="button" onClick={() => { setData(current => ({ ...current, guardians: current.guardians.filter((_, i) => i !== index) })); setDirty(true); }} className="rounded-lg p-2 text-slate-500 hover:bg-red-50 hover:text-red-700" aria-label={`Remove guardian ${index + 1}`}><Trash2 size={16}/></button>}</div><div className="grid gap-3 sm:grid-cols-2"><TextField label="Full names" value={person.fullName} onChange={value => updateGuardian(index, "fullName", value)} error={errors[`guardians.${index}.fullName`]} required/><TextField label="Relationship to learner" value={person.relationship} onChange={value => updateGuardian(index, "relationship", value)} placeholder="Mother, father, guardian…" error={errors[`guardians.${index}.relationship`]} required/><TextField label="ID / passport number" value={person.idNumber} onChange={value => updateGuardian(index, "idNumber", value)}/><TextField label="Phone number" value={person.phone} onChange={value => updateGuardian(index, "phone", value)} placeholder="+254712345678" error={errors[`guardians.${index}.phone`]} required/><TextField label="Alternate phone" value={person.alternatePhone} onChange={value => updateGuardian(index, "alternatePhone", value)} placeholder="+254…"/><TextField label="Email" type="email" value={person.email} onChange={value => updateGuardian(index, "email", value)}/><TextField label="Occupation" value={person.occupation} onChange={value => updateGuardian(index, "occupation", value)}/><TextField label="Employer" value={person.employer} onChange={value => updateGuardian(index, "employer", value)}/><TextField label="Home address" value={person.homeAddress} onChange={value => updateGuardian(index, "homeAddress", value)}/><TextField label="Work address" value={person.workAddress} onChange={value => updateGuardian(index, "workAddress", value)}/></div><div className="mt-4 grid gap-2 sm:grid-cols-3"><Check checked={person.primaryContact} onChange={value => setData(current => ({ ...current, guardians: current.guardians.map((item, row) => ({ ...item, primaryContact: row === index ? value : value ? false : item.primaryContact })) }))}>Primary contact</Check><Check checked={person.paysFees} onChange={value => updateGuardian(index, "paysFees", value)}>Pays school fees</Check><Check checked={person.whatsapp} onChange={value => updateGuardian(index, "whatsapp", value)}>WhatsApp number</Check></div></article>)}<button type="button" disabled={data.guardians.length >= 5} onClick={() => { setData(current => ({ ...current, guardians: [...current.guardians, { ...blankGuardian(), relationship: "Guardian", primaryContact: false, paysFees: false }] })); setDirty(true); }} className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-blue-200 bg-blue-50 px-4 text-sm font-bold text-blue-800 disabled:opacity-50"><Plus size={17}/> Add another guardian</button></div><div className="mt-7 grid gap-5 lg:grid-cols-2"><ContactGroup title="Emergency contacts" description="Add at least two trusted contacts." people={data.emergencyContacts} onAdd={() => { setData(current => ({ ...current, emergencyContacts: [...current.emergencyContacts, blankContact()] })); setDirty(true); }} onRemove={index => { setData(current => ({ ...current, emergencyContacts: current.emergencyContacts.filter((_, row) => row !== index) })); setDirty(true); }} onUpdate={(index, key, value) => updateContact("emergencyContacts", index, key, value)} errors={errors} prefix="emergencyContacts"/><ContactGroup title="Authorized pick-up persons" description="Optional people approved to collect the learner." people={data.pickupPersons} onAdd={() => { setData(current => ({ ...current, pickupPersons: [...current.pickupPersons, blankContact()] })); setDirty(true); }} onRemove={index => { setData(current => ({ ...current, pickupPersons: current.pickupPersons.filter((_, row) => row !== index) })); setDirty(true); }} onUpdate={(index, key, value) => updateContact("pickupPersons", index, key, value)} errors={errors} prefix="pickupPersons" optional/></div></section>}
        {step === 4 && <section><SectionHeading title="Health and wellbeing" description="These notes are restricted to authorized school leaders and the learner's class teacher."/><div className="mb-5 flex items-start gap-3 rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-950"><ShieldCheck className="mt-0.5 shrink-0" size={18}/><p>Share only information the school needs to keep the learner safe and supported. Health information is stored separately and is not available to finance staff.</p></div><div className="grid gap-4 sm:grid-cols-2"><AreaField label="Known illnesses or conditions" value={data.health.knownConditions} onChange={value => updateSection("health", "knownConditions", value)}/><AreaField label="Allergies" value={data.health.allergies} onChange={value => updateSection("health", "allergies", value)}/><AreaField label="Current medication" value={data.health.currentMedication} onChange={value => updateSection("health", "currentMedication", value)}/><AreaField label="Disabilities or special learning needs" value={data.health.specialNeeds} onChange={value => updateSection("health", "specialNeeds", value)}/><Field label="Blood group"><select value={data.health.bloodGroup} onChange={event => updateSection("health", "bloodGroup", event.target.value)} className={selectClass}><option value="">Not provided</option>{["A+","A-","B+","B-","AB+","AB-","O+","O-"].map(value => <option key={value}>{value}</option>)}</select></Field><TextField label="Doctor or preferred hospital" value={data.health.doctorOrHospital} onChange={value => updateSection("health", "doctorOrHospital", value)}/><TextField label="Immunization status" value={data.health.immunizationStatus} onChange={value => updateSection("health", "immunizationStatus", value)}/><TextField label="Health insurance (e.g. SHA)" value={data.health.healthInsurance} onChange={value => updateSection("health", "healthInsurance", value)}/></div></section>}
        {step === 5 && <section><SectionHeading title="Documents" description="JPEG, PNG or PDF only. Files stay private and are never exposed through public upload URLs. Maximum file size: 4 MB."/><div className="mb-4 grid gap-2 sm:grid-cols-2"><StatusBox done={docsByCategory.has("PASSPORT_PHOTO")} label="Learner passport photo" required/><StatusBox done={docsByCategory.has("BIRTH_CERTIFICATE")} label="Birth certificate" required/><StatusBox done={docsByCategory.has("PREVIOUS_REPORT")} label="Previous school report / leaving certificate"/><StatusBox done={docsByCategory.has("IMMUNIZATION_CARD")} label="Immunization card"/><StatusBox done={docsByCategory.has("PARENT_ID")} label="Parent or guardian ID copy"/></div><div className="grid gap-3 sm:grid-cols-2">{categories.map(([category, label]) => <Field key={category} label={label} hint={category === "PASSPORT_PHOTO" ? "Photo files only · up to 4 MB" : "JPEG, PNG or PDF · up to 4 MB"}><input aria-label={`Upload ${label}`} type="file" accept={category === "PASSPORT_PHOTO" ? "image/jpeg,image/png" : "image/jpeg,image/png,application/pdf"} onChange={event => void upload(category, event.target.files?.[0])} className="mt-1.5 min-h-12 w-full rounded-xl border border-slate-200 bg-white p-2 text-xs text-slate-700 file:mr-3 file:min-h-8 file:rounded-lg file:border-0 file:bg-blue-50 file:px-3 file:text-xs file:font-bold file:text-blue-800"/></Field>)}</div><div className="mt-5 space-y-2">{documents.map(document => <div key={document.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-200 bg-white p-3"><div className="flex min-w-0 items-center gap-3"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-blue-50 text-blue-700">{document.contentType.startsWith("image/") ? <FileImage size={18}/> : <FileCheck2 size={18}/>}</span><span className="min-w-0"><span className="block truncate text-sm font-bold text-slate-800">{document.originalName}</span><span className="text-xs text-slate-500">{admissionDocumentCategoryLabels[document.category as keyof typeof admissionDocumentCategoryLabels]} · {(document.sizeBytes / 1024).toFixed(0)} KB</span></span></div><div className="flex items-center gap-2"><a href={`/api/admissions/${draft.id}/documents/${document.id}`} target="_blank" rel="noreferrer" className="min-h-10 rounded-lg px-3 py-2 text-xs font-bold text-blue-800 hover:bg-blue-50">Preview</a><button type="button" onClick={() => void removeDocument(document)} className="grid h-10 w-10 place-items-center rounded-lg text-slate-500 hover:bg-red-50 hover:text-red-700" aria-label={`Remove ${document.originalName}`}><Trash2 size={16}/></button></div></div>)}{documents.length === 0 && <p className="rounded-xl border border-dashed border-slate-300 p-5 text-center text-sm text-slate-500">No files uploaded yet. You can continue and add missing documents later.</p>}</div></section>}
        {step === 6 && <section><SectionHeading title="Fees and hand-off" description="Record the family's selections for the Accountant. The Secretary does not collect or record payments."/><div className="mb-5 flex items-start gap-3 rounded-2xl border border-blue-100 bg-blue-50 p-4 text-sm text-blue-950"><FileCheck2 className="mt-0.5 shrink-0" size={18}/><p>The first invoice is prepared by the Accountant using the Head Teacher&apos;s approved fee structure. This admission records optional service requests and the responsible fee payer; no price is invented here.</p></div><div className="grid gap-4 sm:grid-cols-2"><TextField label="Term of admission" value={data.fee.term} onChange={value => updateSection("fee", "term", value)} placeholder="e.g. 2026 Term 3" error={errors.term} required/><Field label="Who will pay fees?"><select value={data.fee.feePayerGuardian} onChange={event => updateSection("fee", "feePayerGuardian", event.target.value)} className={selectClass}><option value="">Select a guardian</option>{data.guardians.map((person, index) => <option key={index} value={person.fullName}>{person.fullName || `Guardian ${index + 1}`}</option>)}</select></Field></div><div className="mt-5"><p className="mb-2 text-sm font-bold text-slate-800">Optional services requested</p><div className="grid gap-2 sm:grid-cols-2">{[["TRANSPORT","Transport"],["LUNCH","Lunch"],["BOARDING","Boarding"],["UNIFORM","Uniform"],["ACTIVITY","Activity programme"]].map(([value,label]) => <Check key={value} checked={data.fee.requestedOptionalItems.includes(value)} onChange={checked => updateSection("fee", "requestedOptionalItems", checked ? [...data.fee.requestedOptionalItems, value] : data.fee.requestedOptionalItems.filter(item => item !== value))}>{label}</Check>)}</div></div><div className="mt-4"><AreaField label="Handoff note for the Accountant" value={data.fee.handoffNote} onChange={value => updateSection("fee", "handoffNote", value)}/></div></section>}
        {step === 7 && <section><SectionHeading title="Review and submit" description="Review the admission summary, confirm consent, and send it for Head Teacher approval."/><div className="grid gap-3 sm:grid-cols-2"><SummaryCard title="Learner" value={`${data.learner.fullName || "Name missing"} · ${data.learner.grade}`} detail={`${data.learner.gender} · DOB ${data.learner.dateOfBirth || "not provided"}`}/><SummaryCard title="Residence" value={`${data.residence.village || "Area missing"}, ${data.residence.ward || "Ward missing"}`} detail={`${data.residence.subCounty}, ${data.residence.county}`}/><SummaryCard title="Family contacts" value={`${data.guardians.length} guardian${data.guardians.length === 1 ? "" : "s"}`} detail={`${data.emergencyContacts.length} emergency contacts · ${data.pickupPersons.length} authorized pick-up`}/><SummaryCard title="Fee hand-off" value={data.fee.term || "Term missing"} detail={`${data.fee.feePayerGuardian || "Fee payer missing"} · ${data.fee.requestedOptionalItems.join(", ") || "No optional services"}`}/></div><section className="mt-5 rounded-2xl border border-slate-200 bg-slate-50/70 p-4"><h3 className="font-extrabold text-slate-900">Admission documents</h3><div className="mt-3 grid gap-2 sm:grid-cols-2">{["PASSPORT_PHOTO", "BIRTH_CERTIFICATE"].map(category => <StatusBox key={category} done={docsByCategory.has(category)} label={admissionDocumentCategoryLabels[category as keyof typeof admissionDocumentCategoryLabels]} required />)}{documents.filter(document => !["PASSPORT_PHOTO", "BIRTH_CERTIFICATE"].includes(document.category)).map(document => <StatusBox key={document.id} done label={document.originalName}/>)}</div><p className="mt-3 text-xs text-slate-500">Missing required documents remain listed on the printed form for office follow-up.</p></section><label className="mt-5 flex cursor-pointer gap-3 rounded-2xl border border-blue-200 bg-blue-50/60 p-4 text-sm leading-6 text-slate-800"><input type="checkbox" checked={data.consent} onChange={event => { setData(current => ({ ...current, consent: event.target.checked })); setDirty(true); }} className="mt-1 h-4 w-4 shrink-0 rounded border-slate-300 text-blue-700 focus:ring-blue-600"/><span><strong>Consent to process learner information.</strong> I confirm that the details provided are accurate and consent to Mary Royal School processing this learner&apos;s personal data for admission, education, safeguarding and school administration under the Kenya Data Protection Act 2019. Health information is restricted to authorized school staff.</span></label><p className="mt-2 text-xs text-slate-500">Submission creates a learner record with a pending admission status. The Head Teacher must approve it before the learner is enrolled.</p></section>}
      </div>
      {draft.status === "DRAFT" && <div className="mt-6 flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 pt-5"><button type="button" onClick={() => void previous()} disabled={step === 1 || busy} className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-slate-200 px-4 text-sm font-bold text-slate-700 hover:bg-slate-50 disabled:opacity-40"><ArrowLeft size={17}/> Previous</button><span className="text-xs text-slate-500">{dirty ? "Saving your latest changes…" : "Your draft stays private and can be resumed."}</span>{step < 7 ? <button type="button" onClick={() => void next()} disabled={busy || saving} className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-blue-700 px-5 text-sm font-bold text-white shadow-sm hover:bg-blue-800 disabled:opacity-60">{busy ? <LoaderCircle className="animate-spin" size={17}/> : null} Continue <ArrowRight size={17}/></button> : <button type="button" onClick={() => void submitAdmission()} disabled={busy || saving || !data.consent} className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-blue-700 px-5 text-sm font-bold text-white shadow-sm hover:bg-blue-800 disabled:cursor-not-allowed disabled:opacity-50">{busy ? <LoaderCircle className="animate-spin" size={17}/> : <CheckIcon size={17}/>} Submit admission</button>}</div>}
    </form>
  </main>;
}

function stepForPath(path: PropertyKey | undefined) { if (path === "learner") return 1; if (path === "residence") return 2; if (["guardians", "emergencyContacts", "pickupPersons"].includes(String(path))) return 3; if (path === "health") return 4; if (path === "documents") return 5; if (path === "fee") return 6; return 7; }
function SectionHeading({ title, description }: { title: string; description: string }) { return <header className="mb-5"><h2 className="text-xl font-extrabold tracking-tight text-slate-950">{title}</h2><p className="mt-1 text-sm text-slate-500">{description}</p></header>; }
function ContactGroup({ title, description, people, onAdd, onRemove, onUpdate, errors, prefix, optional = false }: { title: string; description: string; people: Contact[]; onAdd: () => void; onRemove: (index: number) => void; onUpdate: (index: number, key: keyof Contact, value: string) => void; errors: Record<string, string>; prefix: string; optional?: boolean }) { return <section className="rounded-2xl border border-slate-200 bg-white p-4"><div className="mb-3"><h3 className="font-extrabold text-slate-900">{title}</h3><p className="mt-1 text-xs text-slate-500">{description}</p></div>{people.map((person, index) => <div key={index} className="mb-4 rounded-xl bg-slate-50 p-3"><div className="mb-2 flex items-center justify-between"><p className="text-xs font-bold text-slate-600">Contact {index + 1}</p><button type="button" onClick={() => onRemove(index)} aria-label={`Remove ${title} ${index + 1}`} className="rounded-lg p-1.5 text-slate-500 hover:bg-red-50 hover:text-red-700"><Trash2 size={15}/></button></div><div className="space-y-3"><TextField label="Full name" value={person.fullName} onChange={value => onUpdate(index, "fullName", value)} error={errors[`${prefix}.${index}.fullName`]} required/><TextField label="Relationship" value={person.relationship} onChange={value => onUpdate(index, "relationship", value)} error={errors[`${prefix}.${index}.relationship`]} required/><TextField label="Phone number" value={person.phone} onChange={value => onUpdate(index, "phone", value)} placeholder="+254712345678" error={errors[`${prefix}.${index}.phone`]} required/></div></div>)}<button type="button" onClick={onAdd} disabled={people.length >= (optional ? 10 : 5)} className="inline-flex min-h-10 items-center gap-1 rounded-lg px-3 text-xs font-bold text-blue-800 hover:bg-blue-50 disabled:opacity-50"><Plus size={15}/> Add {optional ? "person" : "contact"}</button></section>; }
function StatusBox({ done, label, required = false }: { done: boolean; label: string; required?: boolean }) { return <div className={`flex items-center gap-2 rounded-xl border px-3 py-2.5 text-xs font-semibold ${done ? "border-emerald-200 bg-emerald-50 text-emerald-800" : "border-slate-200 bg-white text-slate-600"}`}><span className={`grid h-5 w-5 place-items-center rounded-full ${done ? "bg-emerald-600 text-white" : "bg-slate-100 text-slate-500"}`}>{done ? <CheckIcon size={12}/> : "·"}</span>{label}{required && <span className="ml-auto text-[10px] font-bold uppercase tracking-wider text-blue-700">Required</span>}</div>; }
function SummaryCard({ title, value, detail }: { title: string; value: string; detail: string }) { return <article className="rounded-2xl border border-slate-200 bg-white p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-blue-700">{title}</p><p className="mt-2 font-extrabold text-slate-950">{value}</p><p className="mt-1 text-xs text-slate-500">{detail}</p></article>; }
